// of this distribution and at http://opencv.org/license.html.

#include "test_precomp.hpp"

using namespace std;

namespace opencv_test { namespace {

typedef TestWithParam<cv::VideoCaptureAPIs> VideoCaptureAPITests;
// Related issues:
//   https://github.com/opencv/opencv/issues/15499
//   https://github.com/opencv/opencv/issues/22088
//   https://github.com/opencv/opencv/issues/26795
TEST_P(VideoCaptureAPITests, mp4_orientation_integration)
{
    cv::VideoCaptureAPIs api = GetParam();
    if (!videoio_registry::hasBackend(api))
        throw SkipTestException("backend " + std::to_string(static_cast<int>(api)) + " was not found");
    std::string video_file = cvtest::TS::ptr()->get_data_path() + "video/rotated_metadata.mp4";
    cv::VideoCapture cap;
    EXPECT_NO_THROW(cap.open(video_file, api));
    ASSERT_TRUE(cap.isOpened())
        << "Can't open the video: " << video_file << " with backend " << api << std::endl;
    double orientationMeta = cap.get(cv::CAP_PROP_ORIENTATION_META);
    EXPECT_EQ(90.0, orientationMeta)
        << "Expected the metadata to indicate 90 degrees rotation.";
    double autoRotate = cap.get(cv::CAP_PROP_ORIENTATION_AUTO);
    EXPECT_EQ(1.0, autoRotate)
        << "Expected CAP_PROP_ORIENTATION_AUTO to be ON (1.0) by default.";
    cv::Size sizeRotated(
        static_cast<int>(cap.get(cv::CAP_PROP_FRAME_WIDTH)),
        static_cast<int>(cap.get(cv::CAP_PROP_FRAME_HEIGHT))
    );
    EXPECT_EQ(270, sizeRotated.width);
    EXPECT_EQ(480, sizeRotated.height);
    cv::Mat frame;
    cap >> frame;
    ASSERT_FALSE(frame.empty()) << "Failed to retrieve a frame (auto-rotated)!";
    EXPECT_EQ(270, frame.cols);
    EXPECT_EQ(480, frame.rows);
    EXPECT_TRUE(cap.set(cv::CAP_PROP_ORIENTATION_AUTO, 0.0))
        << "Could not disable CAP_PROP_ORIENTATION_AUTO.";
    EXPECT_EQ(0.0, cap.get(cv::CAP_PROP_ORIENTATION_AUTO))
        << "Expected CAP_PROP_ORIENTATION_AUTO to be OFF (0.0).";
    cv::Size sizeUnrotated(
        static_cast<int>(cap.get(cv::CAP_PROP_FRAME_WIDTH)),
        static_cast<int>(cap.get(cv::CAP_PROP_FRAME_HEIGHT))
    );
    EXPECT_EQ(480, sizeUnrotated.width);
    EXPECT_EQ(270, sizeUnrotated.height);
    cap >> frame;
    ASSERT_FALSE(frame.empty()) << "Failed to retrieve a frame (non-rotated)!";
    EXPECT_EQ(480, frame.cols);
    EXPECT_EQ(270, frame.rows);
}

INSTANTIATE_TEST_CASE_P(videoio, VideoCaptureAPITests, testing::Values(CAP_FFMPEG, CAP_AVFOUNDATION));

}} // namespace
